<?php require_once __DIR__.'/../includes/header.php';checkAuth(['economia','admin']);$db=getDBConnection();$today=date('Y-m-d');$sales=(float)($db->query("SELECT COALESCE(SUM(monto_total_cup),0) FROM facturas WHERE tipo='comprobante' AND date(fecha)='$today'")->fetchColumn());$stock=(float)($db->query('SELECT COALESCE(SUM(stock_actual*precio_compra_unidad),0) FROM insumos')->fetchColumn());?><div class="card"><h1>Economía</h1><p class="muted">Control de compras, almacén, caja y cuenta bancaria.</p></div><div class="grid grid-3"><div class="stat">Ventas del día<strong><?=money($sales)?></strong></div><div class="stat">Valor del inventario<strong><?=money($stock)?></strong></div><div class="stat">Fecha<strong><?=h($today)?></strong></div></div><div class="grid grid-3" style="margin-top:18px"><a class="card" href="almacen.php"><h3>📦 Almacén</h3><p class="muted">Existencias y costos.</p></a><a class="card" href="compras.php"><h3>🧾 Compras</h3><p class="muted">Entradas y facturas de proveedores.</p></a><a class="card" href="despachos.php"><h3>↘ Despachos</h3><p class="muted">Salidas diarias y reporte PDF.</p></a><a class="card" href="caja.php"><h3>▣ Caja</h3><p class="muted">Cuadre diario y mensual.</p></a><a class="card" href="banco.php"><h3>🏦 Banco</h3><p class="muted">Transferencias y movimientos.</p></a></div><?php require_once __DIR__.'/../includes/footer.php';?>
